from pathlib import Path
import json
r=Path(__file__).parent;m=json.loads((r/'registration-manifest.json').read_text())
css='''body{margin:0;padding:16px;color:var(--foreground);font:15px system-ui}h1{font-size:22px}button,select,input{font:inherit}button,select{min-height:36px}label{display:inline-flex;align-items:center;gap:5px;margin:4px 10px 4px 0}.tools{color:#24130d;position:sticky;top:0;padding:8px;background:#f9fbf4;z-index:5;border-bottom:1px solid #b7c597}.viewport{position:relative;overflow:hidden;height:600px;background:#dadbd5;touch-action:none;border:1px solid #687e59;cursor:grab}.scene{position:absolute;transform-origin:0 0;overflow:hidden}.reference,.vector,.contour,.dots{position:absolute;left:0;top:0;pointer-events:none}.vector{background:#24130d}.scene[data-key=features] .vector,.scene[data-key=collie] .vector{background:#f9fbf4}.contour{opacity:.9}.reference{max-width:none}.status{font-size:14px;line-height:1.5}table{border-collapse:collapse}th,td{padding:6px 14px;text-align:left;border-bottom:1px solid #b7c597}summary{padding:12px;cursor:pointer}'''
js='''const data=DATA,viewport=document.querySelector('.viewport'),scene=document.querySelector('.scene'),ref=document.querySelector('.reference'),vec=document.querySelector('.vector'),contour=document.querySelector('.contour'),dots=document.querySelector('.dots'),region=document.querySelector('#region'),phase=document.querySelector('#phase'),mode=document.querySelector('#mode'),alpha=document.querySelector('#alpha'),zoom=document.querySelector('#zoom');let scale=1,px=0,py=0,drag=null,blink=false;function transform(){scene.style.transform=`translate(${px}px,${py}px) scale(${scale})`}function update(){const k=region.value,s=data.regions[k],p=phase.value;scene.dataset.key=k;scene.style.width=s.w+'px';scene.style.height=s.h+'px';ref.src=document.getElementById('asset-'+k+'-reference').src;ref.style.width='1024px';ref.style.top=-s.crop[1]+'px';vec.src=document.getElementById('asset-'+k+'-'+p).src;contour.src=document.getElementById('asset-'+k+'-'+p+'-contour').src;for(const e of [vec,contour,dots]){e.style.width=s.w+'px';e.style.height=s.h+'px'}dots.setAttribute('viewBox',`0 0 ${s.w} ${s.h}`);dots.innerHTML=data.samples.filter(a=>a.region===k&&a.reference!==null).map(a=>{const y=a[p];return`<circle cx="${a.x}" cy="${a.reference}" r="3" fill="#00a8ff"><title>Raster ${a.boundary}: ${a.reference}</title></circle>`+(y===null?'':`<line x1="${a.x}" y1="${a.reference}" x2="${a.x}" y2="${y}" stroke="#f000cc" stroke-width="2"/><circle cx="${a.x}" cy="${y}" r="2" fill="#f000cc"><title>SVG ${y}; signed offset ${a[p+'Offset']}px</title></circle>`) }).join('');document.querySelector('.status').textContent=s.production+' — '+JSON.stringify(data.summary[k][p])+'. Local selected samples only; missing intersections are recorded separately.';apply()}function apply(){const v=+alpha.value/100,m=mode.value;ref.style.visibility='visible';vec.style.visibility='visible';vec.style.opacity=m==='opacity'?v:1;vec.style.clipPath=m==='wipe'?`inset(0 ${100-alpha.value}% 0 0)`:'none';contour.style.display=m==='contour'?'block':'none';dots.style.display=document.querySelector('#landmarks').checked?'block':'none';if(m==='contour')vec.style.visibility='hidden';if(m==='blink'){ref.style.visibility=blink?'hidden':'visible';vec.style.visibility=blink?'visible':'hidden'}}function fit(){const s=data.regions[region.value];scale=Math.min(viewport.clientWidth/s.w,viewport.clientHeight/s.h);zoom.value=scale;px=py=0;transform()}for(const e of [region,phase,mode])e.onchange=()=>{update();if(e===region)fit()};alpha.oninput=apply;document.querySelector('#landmarks').onchange=apply;zoom.oninput=()=>{scale=+zoom.value;transform()};document.querySelector('#fit').onclick=fit;document.querySelector('#native').onclick=()=>{scale=1;zoom.value=1;px=py=0;transform()};viewport.onpointerdown=e=>{drag=[e.clientX-px,e.clientY-py];viewport.setPointerCapture(e.pointerId)};viewport.onpointermove=e=>{if(drag){px=e.clientX-drag[0];py=e.clientY-drag[1];transform()}};viewport.onpointerup=()=>drag=null;setInterval(()=>{if(mode.value==='blink'){blink=!blink;apply()}},650);update();fit();Promise.all([...document.querySelectorAll('[hidden] img')].map(i=>i.decode().then(()=>true).catch(()=>false))).then(ok=>console.log('comparisonAssets',JSON.stringify({count:ok.length,allLoaded:ok.every(Boolean)})));'''.replace('DATA',json.dumps(m))
assets='<div hidden>'+''.join('<img id="asset-'+k+'-'+tag+'" src="'+file+'" alt="Comparison asset">' for k,v in m['regions'].items() for tag,file in [('reference',v['reference']),('before',v['before']),('after',v['after']),('before-contour',k+'-before-contour.svg'),('after-contour',k+'-after-contour.svg')])+'</div>'
rows=''.join(f'<tr><td>{k}</td><td>{s["before"]["samples"]} → {s["after"]["samples"]}</td><td>{s["before"]["meanAbsolute"]} → {s["after"]["meanAbsolute"]}</td><td>{s["before"]["maxAbsolute"]} → {s["after"]["maxAbsolute"]}</td></tr>' for k,s in m['summary'].items())
(r/'registered-comparison.html').write_text('''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registered raster / SVG comparison</title><style>'''+css+'''</style></head><body>'''+assets+'''<h1>Registered raster / SVG comparison</h1><p>Same native coordinates. Drag to pan; zoom moves both layers together. Compare original and refined authoring curves before evaluating responsive page placement. Blue dots mark sampled raster boundaries; magenta dots/lines show SVG displacement. AI text, cards, phones, shading and orange dog mane are excluded from measurements.</p><div class="tools"><label>Region <select id="region"><option value="hero">A hero</option><option value="features">A features</option><option value="collie">Lower C Collie</option></select></label><label>SVG <select id="phase"><option value="after">Refined</option><option value="before">Original</option></select></label><label>Compare <select id="mode"><option value="contour">High-contrast contour</option><option value="opacity">Opacity overlay</option><option value="wipe">Wipe slider</option><option value="blink">Rapid A/B blink</option></select></label><label>Amount <input id="alpha" type="range" min="0" max="100" value="50"></label><label>Zoom <input id="zoom" type="range" min=".3" max="4" step=".01" value="1"></label><button id="fit">Fit</button> <button id="native">Native1:1</button><label><input id="landmarks" type="checkbox" checked>Landmarks</label></div><div class="viewport"><div class="scene"><img class="reference" alt="Registered selected raster crop"><img class="vector" alt="Registered SVG"><img class="contour" alt="High contrast SVG contour"><svg class="dots" xmlns="http://www.w3.org/2000/svg"></svg></div></div><p class="status"></p><details><summary>Local exposed-boundary measurements and limitations</summary><table><thead><tr><th>Region</th><th>Sample intersections</th><th>Mean absolute offset px</th><th>Maximum absolute offset px</th></tr></thead><tbody>'''+rows+'''</tbody></table><p>Counts differ where the original curve did not intersect a selected window. This is a sparse, reproducible diagnostic, not a whole-image fit score. Reference thresholds and windows are in registration-manifest.json and compare-registered.py. No global transform was inferred. The page’s own symmetric divider and foreground remain independent.</p></details><script>'''+js+'''</script></body></html>''');print(r/'registered-comparison.html')
